package com.nthexperience.desktop;

import android.app.*;
import android.content.*;
import android.content.pm.ActivityInfo;
import android.content.res.Configuration;
import android.os.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.concurrent.*;
import java.util.function.Predicate;

/** Run on disposable emulators. Exercises presentation identity as well as the visible controls. */
public final class AeroSmoke extends LauncherSmoke {
    private MainActivity activity;
    private View root;
    private boolean verifyBoot,legacy;
    private final BlockingQueue<MainActivity> resumed=new LinkedBlockingQueue<>();
    private final Application.ActivityLifecycleCallbacks lifecycle=new Application.ActivityLifecycleCallbacks(){public void onActivityResumed(Activity a){if(a instanceof MainActivity)resumed.offer((MainActivity)a);}public void onActivityCreated(Activity a,Bundle b){}public void onActivityStarted(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};
    @Override public void onCreate(Bundle args){verifyBoot=args!=null&&"true".equals(args.getString("verify_boot"));legacy=args!=null&&"legacy".equals(args.getString("suite"));super.onCreate(args);}
    @Override public void onStart(){if(legacy){super.onStart();return;}Bundle result=new Bundle();Application app=(Application)getTargetContext().getApplicationContext();app.registerActivityLifecycleCallbacks(lifecycle);try{
        DesktopStore store=new DesktopStore(getTargetContext());android.content.SharedPreferences session=getTargetContext().getSharedPreferences(StartupExperience.SESSION,0);
        if(!verifyBoot){store.prefs.edit().putInt("startup_mode",0).putBoolean("startup_sound",false).putBoolean("welcome_on_start",false).putBoolean("reduce_motion",false).commit();session.edit().putBoolean("seen",true).putBoolean("welcome_seen",true).putInt("boot",StartupExperience.boot(getTargetContext())).commit();}
        shell("cmd role add-role-holder --user 0 android.app.role.HOME com.nthexperience.desktop");
        Intent launch=new Intent(Intent.ACTION_MAIN).setComponent(new ComponentName(getTargetContext(),MainActivity.class)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);activity=(MainActivity)startActivitySync(launch);root=activity.getWindow().getDecorView();waitForIdleSync();Thread.sleep(450);refresh();
        if(verifyBoot){rebootChecks(store,session);result.putString("stream","PASS: real emulator reboot plays once; repeated Home and Activity recreation do not replay.\n");}
        else{appearance(store);startup(store,session);result.putString("stream","PASS: independent Aero color/intensity/transparency, active/inactive windows, actual animated minimize/restore without note loss, backward-compatible backup settings, first-run startup/skip/Welcome Center, real Home suppression, preview/rotation cancellation, reduced motion, original-chime setting and replay video.\n");}
        app.unregisterActivityLifecycleCallbacks(lifecycle);finish(Activity.RESULT_OK,result);
    }catch(Throwable failure){java.io.StringWriter details=new java.io.StringWriter();failure.printStackTrace(new java.io.PrintWriter(details));try{shot("aero-failure.png");}catch(Exception ignored){}app.unregisterActivityLifecycleCallbacks(lifecycle);result.putString("stream","FAIL: "+details+"\n");finish(Activity.RESULT_CANCELED,result);}}
    private void appearance(DesktopStore store)throws Exception{
        progress("checking independent glass controls");int wallpaper=store.prefs.getInt("wallpaper",0);setting("Window Color and Appearance");click("@control","Glass color: Lavender");check(store.prefs.getInt("aero_color",-1)==4&&store.prefs.getInt("wallpaper",0)==wallpaper,"Glass color does not change wallpaper");
        SeekBar intensity=(SeekBar)find(tool("@control"),v->"Color intensity".equals(v.getContentDescription()));check(intensity!=null,"Intensity slider exists");ui(()->{intensity.requestFocus();intensity.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_DPAD_RIGHT));intensity.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_UP,KeyEvent.KEYCODE_DPAD_RIGHT));});check(store.prefs.getInt("aero_intensity",45)>45,"Keyboard-accessible intensity changes the real preference");click("@control","Enable glass transparency");check(!store.prefs.getBoolean("aero_transparency",true),"Opaque mode is saved");shot("aero-opaque.png");click("@control","Enable glass transparency");shot("aero-colors.png");
        JSONObject backup=DesktopBackup.snapshot(store);DesktopBackup.Plan plan=DesktopBackup.parse(backup.toString());check(plan.values.get("aero_color").equals(4)&&plan.values.get("aero_intensity").equals(store.prefs.getInt("aero_intensity",0)),"Backup preserves independent glass controls");check(!backup.getJSONObject("settings").has("boot")&&!backup.getJSONObject("settings").has("seen"),"Device playback identity is excluded from desktop backups");JSONObject old=new JSONObject(backup.toString());for(String key:new String[]{"aero_color","aero_intensity","aero_transparency","startup_mode","startup_sound","reduce_motion","welcome_on_start"})old.getJSONObject("settings").remove(key);check(DesktopBackup.parse(old.toString()).string("note","").equals(store.prefs.getString("note","")),"Existing 0.5.0 backup settings remain readable");JSONObject invalid=new JSONObject(backup.toString());invalid.getJSONObject("settings").put("aero_intensity",new JSONObject().put("type","int").put("value",101));boolean rejected=false;try{DesktopBackup.parse(invalid.toString());}catch(JSONException expected){rejected=true;}check(rejected,"Invalid intensity cannot enter preferences");
        click("@control","Close window");ui(()->activity.open("@notes"));DesktopWindow notes=tool("@notes");ui(()->activity.open("@computer"));DesktopWindow computer=tool("@computer");check(computer.active()&&!notes.active(),"Only the foreground Nth window is active");ui(notes::restore);check(notes.active()&&!computer.active(),"Restoring a window changes its active caption");shot("aero-windows.png");
        progress("checking actual motion without changing saved window geometry or note text");shell("settings put global animator_duration_scale 1");shell("settings put global window_animation_scale 1");shell("settings put global transition_animation_scale 1");Thread.sleep(150);check(Aero.motion(activity),"System animation setting enables motion");EditText editor=(EditText)find(notes,v->"Notepad text".equals(v.getContentDescription()));String note=editor.getText().toString();JSONObject before=notes.geometry();ui(()->{View minimize=find(notes,v->"Minimize window".equals(v.getContentDescription()));minimize.performClick();check(notes.minimizing(),"Minimize schedules motion toward the taskbar");});condition(()->notes.getScaleX()<1||notes.getVisibility()==View.GONE,"Minimize advances");condition(()->notes.getVisibility()==View.GONE,"Minimize completes");String noteName=store.name("@notes","Notepad");View task=find(v->("Restore "+noteName).equals(v.getContentDescription()));if(task==null)task=find(v->v instanceof TextView&&v.isClickable()&&"Notepad".contentEquals(((TextView)v).getText()));check(task!=null,"Taskbar exposes the minimized note");View restore=task;ui(restore::performClick);condition(()->notes.getVisibility()==View.VISIBLE&&notes.getScaleX()==1&&notes.getAlpha()==1,"Restore settles at normal size and opacity");check(before.toString().equals(notes.geometry().toString())&&note.contentEquals(editor.getText()),"Motion preserves geometry and note contents");click("@notes","Close window");click("@computer","Close window");
    }
    private void startup(DesktopStore store,android.content.SharedPreferences session)throws Exception{
        progress("checking first-run presentation and skip");session.edit().putBoolean("seen",false).putBoolean("welcome_seen",false).commit();MainActivity previous=activity;resumed.clear();runOnMainSync(()->activity.recreate());replacement(previous);await(v->"Nth startup sequence".equals(v.getContentDescription()));Thread.sleep(900);shot("startup-pearl.png");click(null,"Skip startup");await(v->v instanceof DesktopWindow&&"@welcome".equals(((DesktopWindow)v).toolId));check(session.getBoolean("seen",false)&&session.getBoolean("welcome_seen",false),"First-run identity is recorded before it can replay");shot("welcome-center.png");click("@welcome","Close window");int runs=session.getInt("runs",0);
        shell("input keyevent KEYCODE_HOME");Thread.sleep(350);refresh();check(find(v->"Nth startup sequence".equals(v.getContentDescription()))==null&&session.getInt("runs",0)==runs,"Ordinary Home does not replay startup");
        store.prefs.edit().putBoolean("welcome_on_start",true).commit();setting("Startup and Sounds");shot("startup-settings.png");click("@control","Preview startup");await(v->"Nth startup sequence".equals(v.getContentDescription()));previous=activity;resumed.clear();runOnMainSync(()->activity.setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE));replacement(previous);Thread.sleep(450);check(find(v->"Nth startup sequence".equals(v.getContentDescription()))==null&&session.getInt("runs",0)==runs,"Rotation cancels a preview without replay or consumption");check(tool("@welcome")==null,"Rotation does not reopen the optional Welcome Center");store.prefs.edit().putBoolean("welcome_on_start",false).commit();previous=activity;resumed.clear();runOnMainSync(()->activity.setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_PORTRAIT));replacement(previous);await(v->"Preview startup".equals(v.getContentDescription()));
        progress("recording the original startup preview");android.os.ParcelFileDescriptor recording=getUiAutomation().executeShellCommand("screenrecord --time-limit 5 /sdcard/Nth-Desktop-Startup.mp4");Thread.sleep(500);click("@control","Preview startup");await(v->"Nth startup sequence".equals(v.getContentDescription()));Thread.sleep(3300);refresh();check(find(v->"Nth startup sequence".equals(v.getContentDescription()))==null&&session.getInt("runs",0)==runs,"Preview completes without changing first-run or boot identity");Thread.sleep(1400);try(java.io.InputStream in=new android.os.ParcelFileDescriptor.AutoCloseInputStream(recording)){byte[] bytes=new byte[512];while(in.read(bytes)!=-1){}}
        click("@control","Reduce motion");check(store.prefs.getBoolean("reduce_motion",false)&&!Aero.motion(activity),"Reduced motion disables animated windows and orb");click("@control","Preview startup");Thread.sleep(700);check(find(v->"Nth startup sequence".equals(v.getContentDescription()))==null,"Reduced-motion preview finishes promptly");click("@control","Reduce motion");click("@control","Play the original Nth startup chime");check(store.prefs.getBoolean("startup_sound",false),"Chime is opt-in");click("@control","Preview startup");await(v->"Nth startup sequence".equals(v.getContentDescription()));Thread.sleep(950);shell("am start -a android.settings.SETTINGS");Thread.sleep(250);shell("am start -n com.nthexperience.desktop/.MainActivity");await(v->"Preview startup".equals(v.getContentDescription()));check(find(v->"Nth startup sequence".equals(v.getContentDescription()))==null&&session.getInt("runs",0)==runs,"Backgrounding stops a sound-enabled preview and returning does not replay it");click("@control","Play the original Nth startup chime");click("@control","Off");check(store.prefs.getInt("startup_mode",0)==2,"Off is selectable");click("@control","Once per phone reboot");check(store.prefs.getInt("startup_mode",0)==1,"Reboot mode is selectable");
        int boot=StartupExperience.boot(activity);session.edit().putInt("boot",boot).putInt("before_reboot",boot).putInt("before_runs",session.getInt("runs",0)).commit();click("@control","Close window");shell("settings put global animator_duration_scale 0");shell("settings put global window_animation_scale 0");shell("settings put global transition_animation_scale 0");
    }
    private void rebootChecks(DesktopStore store,android.content.SharedPreferences session)throws Exception{
        progress("checking the actual reboot marker after Android starts home");int current=StartupExperience.boot(activity),previous=session.getInt("before_reboot",-1),runs=session.getInt("before_runs",-1);check(current>=0&&current!=previous,"The emulator actually rebooted");long deadline=SystemClock.uptimeMillis()+8000;while(SystemClock.uptimeMillis()<deadline&&(session.getInt("boot",-1)!=current||find(v->"Nth startup sequence".equals(v.getContentDescription()))!=null)){Thread.sleep(150);refresh();}check(store.prefs.getInt("startup_mode",0)==1&&session.getInt("boot",-1)==current&&session.getInt("runs",0)==runs+1,"Exactly one automatic presentation was claimed for this reboot");shell("input keyevent KEYCODE_HOME");Thread.sleep(250);shell("input keyevent KEYCODE_HOME");Thread.sleep(250);refresh();check(session.getInt("runs",0)==runs+1,"Repeated Home in the same boot is instant");MainActivity old=activity;resumed.clear();ui(()->activity.recreate());replacement(old);check(session.getInt("runs",0)==runs+1&&find(v->"Nth startup sequence".equals(v.getContentDescription()))==null,"Recreation does not count as reboot");shot("startup-after-reboot.png");}
    private void setting(String label)throws Exception{ui(()->activity.open("@control"));progress("Control Panel opened: "+label);EditText search=(EditText)find(tool("@control"),v->"Search Control Panel".equals(v.getContentDescription()));check(search!=null,"Control Panel search is available");ui(()->search.setText(label));progress("Control Panel search ready: "+label);click("@control",label);progress("Control Panel page selected: "+label);}
    private DesktopWindow tool(String id){return (DesktopWindow)find(v->v instanceof DesktopWindow&&id.equals(((DesktopWindow)v).toolId));}
    private void click(String id,String label){View view=find(id==null?root:tool(id),v->label.equals(v.getContentDescription()));check(view!=null,"Action is available: "+label);runOnMainSync(view::performClick);}
    private void replacement(MainActivity previous)throws Exception{long deadline=SystemClock.uptimeMillis()+12000;while(SystemClock.uptimeMillis()<deadline){MainActivity next=resumed.poll(1,TimeUnit.SECONDS);if(next!=null&&next!=previous&&!next.isDestroyed()){activity=next;root=next.getWindow().getDecorView();Thread.sleep(120);return;}}throw new AssertionError("Activity replacement did not resume");}
    private void refreshFast(){MainActivity next;while((next=resumed.poll())!=null)if(!next.isDestroyed())activity=next;root=activity.getWindow().getDecorView();}
    private void refresh(){refreshFast();}
    private void await(Predicate<View> test)throws Exception{long deadline=SystemClock.uptimeMillis()+8000;while(SystemClock.uptimeMillis()<deadline){refreshFast();java.util.concurrent.atomic.AtomicBoolean shown=new java.util.concurrent.atomic.AtomicBoolean();runOnMainSync(()->shown.set(find(test)!=null));if(shown.get())return;Thread.sleep(60);}throw new AssertionError("Expected native UI did not appear");}
    private void shot(String name)throws Exception{Thread.sleep(160);android.graphics.Bitmap bitmap=getUiAutomation().takeScreenshot();check(bitmap!=null,"Screenshot available");try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(getTargetContext().getFilesDir(),name))){bitmap.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}finally{bitmap.recycle();}}
    private View find(Predicate<View> match){return find(root,match);}
    private View find(View view,Predicate<View> match){if(view==null||!view.isShown())return null;if(match.test(view))return view;if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++){View found=find(((ViewGroup)view).getChildAt(i),match);if(found!=null)return found;}return null;}
    private void condition(java.util.function.BooleanSupplier test,String message)throws Exception{long end=SystemClock.uptimeMillis()+3000;while(SystemClock.uptimeMillis()<end){java.util.concurrent.atomic.AtomicBoolean okay=new java.util.concurrent.atomic.AtomicBoolean();ui(()->okay.set(test.getAsBoolean()));if(okay.get())return;Thread.sleep(30);}throw new AssertionError(message);}
    private void ui(Runnable runnable){runOnMainSync(runnable);try{Thread.sleep(35);}catch(InterruptedException interrupted){Thread.currentThread().interrupt();throw new AssertionError(interrupted);}}
    private String shell(String cmd)throws Exception{try(android.os.ParcelFileDescriptor descriptor=getUiAutomation().executeShellCommand(cmd);java.io.InputStream input=new android.os.ParcelFileDescriptor.AutoCloseInputStream(descriptor);java.io.ByteArrayOutputStream output=new java.io.ByteArrayOutputStream()){byte[] buffer=new byte[4096];int n;while((n=input.read(buffer))!=-1)output.write(buffer,0,n);return output.toString("UTF-8");}}
    private void progress(String message){Bundle status=new Bundle();status.putString("stream","CHECK: "+message+"\n");sendStatus(1,status);}
    private void check(boolean okay,String message){if(!okay)throw new AssertionError(message);}
}
